        return nums.toSet().size < nums.size
    }
}
```

```swift
class Solution {
    func hasDuplicate(_ nums: [Int]) -> Bool {
        return Set(nums).count < nums.count
    }
}
```

::tabs-end

### Time & Space Complexity

- Time complexity: $O(n)$
- Space complexity: $O(n)$

