func countComponents(n int, edges [][]int) int {
    adj := make([][]int, n)
	visit := make([]bool, n)
	for _, edge := range edges {
		u, v := edge[0], edge[1]
		adj[u] = append(adj[u], v)
		adj[v] = append(adj[v], u)
	}

	bfs := func(node int) {
		q := []int{node}
		visit[node] = true
		for len(q) > 0 {
			cur := q[0]
			q = q[1:]
			for _, nei := range adj[cur] {
				if !visit[nei] {
					visit[nei] = true
					q = append(q, nei)
				}
			}
		}
	}

	res := 0
	for node := 0; node < n; node++ {
		if !visit[node] {
			bfs(node)
			res++
		}
	}
	return res
}
