func NewDSU(n int) *DSU {
	parent := make([]int, n+1)
	size := make([]int, n+1)
	for i := 0; i <= n; i++ {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{Parent: parent, Size: size, Comps: n}
