func (dsu *DSU) Union(u, v int) bool {
	pu, pv := dsu.Find(u), dsu.Find(v)
	if pu == pv {
		return false
	}
	dsu.Comps--
	if dsu.Size[pu] < dsu.Size[pv] {
		pu, pv = pv, pu
	}
	dsu.Size[pu] += dsu.Size[pv]
	dsu.Parent[pv] = pu
	return true
