class Solution {
    constructor() {
        this.adjacencyList = new Map();
    }

    /**
     * @param {number} n
     * @param {number[][]} edges
     * @returns {boolean}
     */
    validTree(n, edges) {
        this.adjacencyList.clear();

        if (n == 1) return edges.length == 0;

        if (edges.length == 0) return false;

        for (let edge of edges) {
            let node1 = edge[0];
            let node2 = edge[1];
            if (!this.adjacencyList.has(node1))
                this.adjacencyList.set(node1, []);
            if (!this.adjacencyList.has(node2))
                this.adjacencyList.set(node2, []);
            this.adjacencyList.get(node1).push(node2);
            this.adjacencyList.get(node2).push(node1);
        }

        let visited = new Set();

        if (!this.depthFirstSearch(0, -1, visited)) return false;

        return visited.size === n;
    }

    /**
     * @param {number} node
     * @param {number} previous
     * @param {Set} visited
     * @returns {boolean}
     */
    depthFirstSearch(node, previous, visited) {
        if (visited.has(node)) return false;

        visited.add(node);

        for (let neighbor of this.adjacencyList.get(node)) {
            if (neighbor === previous) continue;

            if (!this.depthFirstSearch(neighbor, node, visited)) return false;
        }

        return true;
    }
}

