            visited[char] = true
            for neigh in adj[char]! {
                if dfs(neigh) {
                    return true
                }
            }
            visited[char] = false
            res.append(char)
            return false
        }

        for char in adj.keys {
            if dfs(char) {
                return ""
            }
        }

        res.reverse()
        return String(res)
    }
}
