        var q = Deque<Character>()
        for (c, deg) in indegree {
            if deg == 0 {
                q.append(c)
            }
        }

        var res = [Character]()
        while !q.isEmpty {
            let char = q.removeFirst()
            res.append(char)
            for neighbor in adj[char]! {
                indegree[neighbor]! -= 1
                if indegree[neighbor]! == 0 {
                    q.append(neighbor)
                }
            }
        }

        if res.count != indegree.count {
            return ""
        }

