```swift
class DSU {
    private var parent: [Int]
    private var size: [Int]

    init(_ n: Int) {
        parent = Array(0...n)
        size = Array(repeating: 1, count: n + 1)
    }

    func find(_ node: Int) -> Int {
        if parent[node] != node {
            parent[node] = find(parent[node])
        }
        return parent[node]
    }

    func union(_ u: Int, _ v: Int) -> Bool {
        let pu = find(u)
        let pv = find(v)
        if pu == pv {
            return false
        }
        if size[pu] >= size[pv] {
            size[pu] += size[pv]
            parent[pv] = pu
        } else {
            size[pv] += size[pu]
            parent[pu] = pv
        }
        return true
    }
}

class Solution {
    func numIslands(_ grid: [[Character]]) -> Int {
        let ROWS = grid.count
        let COLS = grid[0].count
        let dsu = DSU(ROWS * COLS)

        func index(_ r: Int, _ c: Int) -> Int {
            return r * COLS + c
        }

        let directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        var islands = 0
        var grid = grid

        for r in 0..<ROWS {
            for c in 0..<COLS {
                if grid[r][c] == "1" {
                    islands += 1
                    for dir in directions {
                        let nr = r + dir.0
                        let nc = c + dir.1
                        if nr < 0 || nc < 0 || nr >= ROWS || nc >= COLS || grid[nr][nc] == "0" {
                            continue
                        }
                        if dsu.union(index(r, c), index(nr, nc)) {
                            islands -= 1
                        }
                    }
                }
            }
        }

        return islands
    }
}
