func maxSubArray(nums []int) int {
    memo := make([][2]*int, len(nums)+1)
    for i := range memo {
        memo[i] = [2]*int{nil, nil}
    }

    var dfs func(int, int) int
    dfs = func(i, flag int) int {
        if i == len(nums) {
            if flag == 1 {
                return 0
            }
            return -1000000
        }
        if memo[i][flag] != nil {
            return *memo[i][flag]
        }
        if flag == 1 {
            result := max(0, nums[i]+dfs(i+1, 1))
            memo[i][flag] = &result
        } else {
            result := max(dfs(i+1, 0), nums[i]+dfs(i+1, 1))
            memo[i][flag] = &result
        }
        return *memo[i][flag]
    }

    return dfs(0, 0)
}

