        // Fill the right array
        for (let i = n - 2; i >= 0; i--) {
            right[i] = right[i + 1] * nums[i + 1];
        }

        // Fill the result array
        for (let i = 0; i < n; i++) {
            result[i] = left[i] * right[i];
        }

        return result;
    }
}

