     * @param {number[]} heights
     * @return {number}
     */
    maxArea(heights) {

        let first = 0;
        let second = heights.length - 1;
        let result = 0;

        while(first < second){
            const mini = Math.min(heights[first],heights[second]);
            const volume = (second - first) * mini;

            result = Math.max(volume,result);
            if(heights[second] < heights[first]) second--;
            else first++;
        }

        return result;
    }
