    func reorderList(_ head: ListNode?) {
        func rec(_ root: ListNode?, _ cur: ListNode?) -> ListNode? {
            if cur == nil {
                return root
            }

            var root = rec(root, cur?.next)
            if root == nil {
                return nil
            }

            var tmp: ListNode? = nil
            if root === cur || root?.next === cur {
                cur?.next = nil
            } else {
                tmp = root?.next
                root?.next = cur
                cur?.next = tmp
            }

            return tmp
        }

        rec(head, head?.next)
    }
}
```

