        var tail = dummy

        while let wrapper = heap.popMin() {
            tail.next = wrapper.node
            tail = tail.next!

            if let next = wrapper.node.next {
                heap.insert(NodeWrapper(next))
            }
        }

        return dummy.next
    }
}
```

