        store.append(word)
    }

    func search(_ word: String) -> Bool {
        for w in store {
            if w.count != word.count {
                continue
            }
            var i = 0
            let wArray = Array(w)
            let wordArray = Array(word)
            while i < wArray.count {
                if wArray[i] == wordArray[i] || wordArray[i] == "." {
                    i += 1
