func NewTrieNode() *TrieNode {
	return &TrieNode{children: make(map[byte]*TrieNode)}
}

func (this *TrieNode) addWord(word string) {
	cur := this
	for i := 0; i < len(word); i++ {
		c := word[i]
		if _, found := cur.children[c]; !found {
			cur.children[c] = NewTrieNode()
