    var dfs func(i, flag int) int
    dfs = func(i, flag int) int {
        if i >= len(nums) || (flag == 1 && i == len(nums)-1) {
            return 0
        }
        if memo[i][flag] != -1 {
            return memo[i][flag]
        }

        tmp := flag
        if i == 0 {
            tmp = 1
        }
        memo[i][flag] = max(dfs(i+1, flag), nums[i] + dfs(i+2, tmp))
        return memo[i][flag]
    }

    return max(dfs(0, 1), dfs(1, 0))
}

func max(a, b int) int {
    if a > b {
        return a
    }
    return b
}
