        for (int coin : coins) {
            if (amount - coin >= 0) {
                res = Math.min(res,
                      1 + dfs(coins, amount - coin));
            }
        }
        return res;
    }

    public int coinChange(int[] coins, int amount) {
        int minCoins = dfs(coins, amount);
        return (minCoins >= 1e9) ? -1 : minCoins;
    }
}
