        let trie = Trie()
        for word in wordDict {
            trie.insert(word)
        }

        var dp = Array(repeating: false, count: s.count + 1)
        dp[s.count] = true
        let chars = Array(s)

        var maxLen = 0
        for word in wordDict {
            maxLen = max(maxLen, word.count)
        }

        for i in stride(from: s.count, through: 0, by: -1) {
            for j in i..<min(s.count, i + maxLen) {
                if trie.search(chars, i, j) {
                    dp[i] = dp[j + 1]
                    if dp[i] {
                        break
