func (seg *SegmentTree) Update(i, val int) {
	seg.tree[seg.n+i] = val
	j := (seg.n + i) >> 1
	for j >= 1 {
		seg.tree[j] = max(seg.tree[j<<1], seg.tree[j<<1|1])
		j >>= 1
