func (seg *SegmentTree) Query(l, r int) int {
	if l > r {
		return 0
	}
	res := -1 << 63
	l += seg.n
	r += seg.n + 1
	for l < r {
		if l&1 != 0 {
			res = max(res, seg.tree[l])
			l++
		}
		if r&1 != 0 {
			r--
			res = max(res, seg.tree[r])
		}
		l >>= 1
		r >>= 1
	}
	return res
