func compress(arr []int) []int {
	sortedArr := make([]int, len(arr))
	copy(sortedArr, arr)
	sort.Ints(sortedArr)
	order := make([]int, len(arr))
	for i, num := range arr {
		order[i] = sort.SearchInts(sortedArr, num)
	}
	return order
}

