class SegmentTree {
    private var n: Int
    private var tree: [Int]

    init(_ N: Int) {
        self.n = N
        while (self.n & (self.n - 1)) != 0 {
            self.n += 1
        }
        self.tree = Array(repeating: 0, count: 2 * self.n)
    }

    func update(_ i: Int, _ val: Int) {
        tree[n + i] = val
        var j = (n + i) >> 1
        while j >= 1 {
            tree[j] = max(tree[j << 1], tree[j << 1 | 1])
            j >>= 1
        }
    }

    func query(_ l: Int, _ r: Int) -> Int {
        if l > r {
            return 0
        }
        var res = Int.min
        var l = l + n
        var r = r + n + 1
        while l < r {
            if l & 1 == 1 {
                res = max(res, tree[l])
                l += 1
            }
            if r & 1 == 1 {
                r -= 1
                res = max(res, tree[r])
            }
            l >>= 1
            r >>= 1
        }
        return res
    }
}

