        let n = nums.count
        let segTree = SegmentTree(n)

        var LIS = 0
        for num in nums {
            let curLIS = segTree.query(0, num - 1) + 1
            segTree.update(num, curLIS)
            LIS = max(LIS, curLIS)
        }
        return LIS
    }
