                binary += '1';
            } else {
                binary += '0';
            }
        }

        uint32_t res = 0;
        for (int i = 0; i < 32; i++) {
            if (binary[31 - i] == '1') {
                res |= (1 << i);
            }
        }

        return res;
    }
};
```

