func (st *SegmentTree) build(N int, A []int) {
    st.tree = make([]int, 2*st.n)
    for i := range st.tree {
        st.tree[i] = math.MinInt
    }
    for i := 0; i < N; i++ {
        st.tree[st.n+i] = A[i]
    }
    for i := st.n - 1; i > 0; i-- {
        st.tree[i] = max(st.tree[i<<1], st.tree[i<<1|1])
    }
}

func (st *SegmentTree) Query(l, r int) int {
    res := math.MinInt
    l += st.n
    r += st.n + 1

    for l < r {
        if l&1 == 1 {
            res = max(res, st.tree[l])
            l++
        }
        if r&1 == 1 {
            r--
            res = max(res, st.tree[r])
        }
        l >>= 1
        r >>= 1
    }
    return res
