```kotlin
class SegmentTree(N: Int, A: IntArray) {
    private var n: Int = N
    private var tree: IntArray = IntArray(0)

    init {
        var size = N
        while (Integer.bitCount(size) != 1) {
            size++
        }
        n = size
        build(N, A)
    }

    private fun build(N: Int, A: IntArray) {
        tree = IntArray(2 * n)
        tree.fill(Int.MIN_VALUE)
        for (i in 0 until N) {
            tree[n + i] = A[i]
        }
        for (i in n - 1 downTo 1) {
            tree[i] = maxOf(tree[i * 2], tree[i * 2 + 1])
        }
    }

    fun query(l: Int, r: Int): Int {
        var res = Int.MIN_VALUE
        var left = l + n
        var right = r + n + 1

        while (left < right) {
            if (left % 2 == 1) {
                res = maxOf(res, tree[left])
                left++
            }
            if (right % 2 == 1) {
                right--
                res = maxOf(res, tree[right])
            }
            left /= 2
            right /= 2
        }
        return res
    }
}

class Solution {
    fun maxSlidingWindow(nums: IntArray, k: Int): IntArray {
        val n = nums.size
        val segTree = SegmentTree(n, nums)
        val result = IntArray(n - k + 1)
        for (i in 0..n - k) {
            result[i] = segTree.query(i, i + k - 1)
        }
        return result
    }
}
```

```swift
class SegmentTree {
    private var n: Int
    private var tree: [Int]

    init(_ N: Int, _ A: [Int]) {
        self.n = N
        while (self.n & (self.n - 1)) != 0 {
            self.n += 1
        }
        self.tree = [Int](repeating: Int.min, count: 2 * self.n)
        build(N, A)
    }

    private func build(_ N: Int, _ A: [Int]) {
        for i in 0..<N {
            tree[n + i] = A[i]
        }
        for i in stride(from: n - 1, through: 1, by: -1) {
            tree[i] = max(tree[i << 1], tree[i << 1 | 1])
        }
    }

    func query(_ l: Int, _ r: Int) -> Int {
        var res = Int.min
        var l = l + n
        var r = r + n + 1
        while l < r {
            if l & 1 != 0 {
                res = max(res, tree[l])
                l += 1
            }
            if r & 1 != 0 {
                r -= 1
                res = max(res, tree[r])
            }
            l >>= 1
            r >>= 1
        }
        return res
    }
}

class Solution {
    func maxSlidingWindow(_ nums: [Int], _ k: Int) -> [Int] {
        let n = nums.count
        let segTree = SegmentTree(n, nums)
        var output = [Int]()

        for i in 0...(n - k) {
            output.append(segTree.query(i, i + k - 1))
        }

        return output
    }
}
