type MinIdxSegtree struct {
    n   int
    INF int
    A   []int
    tree []int
}

func NewMinIdxSegtree(N int, A []int) *MinIdxSegtree {
    st := &MinIdxSegtree{
        n:   N,
        INF: 1000000000,
        A:   make([]int, N),
    }
    copy(st.A, A)

    for (st.n & (st.n - 1)) != 0 {
        st.A = append(st.A, st.INF)
        st.n++
    }

    st.tree = make([]int, 2*st.n)
    st.build()
    return st
}

func (st *MinIdxSegtree) build() {
    for i := 0; i < st.n; i++ {
        st.tree[st.n+i] = i
    }

    for j := st.n - 1; j > 0; j-- {
        a := st.tree[j<<1]
        b := st.tree[(j<<1)+1]
        if st.A[a] <= st.A[b] {
            st.tree[j] = a
        } else {
            st.tree[j] = b
        }
    }
}

func (st *MinIdxSegtree) update(i, val int) {
    st.A[i] = val
    j := (st.n + i) >> 1
    for j >= 1 {
        a := st.tree[j<<1]
        b := st.tree[(j<<1)+1]
        if st.A[a] <= st.A[b] {
            st.tree[j] = a
        } else {
            st.tree[j] = b
        }
        j >>= 1
    }
}

func (st *MinIdxSegtree) query(ql, qh int) int {
    return st.queryHelper(1, 0, st.n-1, ql, qh)
}

func (st *MinIdxSegtree) queryHelper(node, l, h, ql, qh int) int {
    if ql > h || qh < l {
        return st.INF
    }
    if l >= ql && h <= qh {
        return st.tree[node]
    }
    a := st.queryHelper(node<<1, l, (l+h)>>1, ql, qh)
    b := st.queryHelper((node<<1)+1, ((l+h)>>1)+1, h, ql, qh)
    if a == st.INF {
        return b
    }
    if b == st.INF {
        return a
    }
    if st.A[a] <= st.A[b] {
        return a
    }
    return b
}

func getMaxArea(heights []int, l, r int, st *MinIdxSegtree) int {
    if l > r {
        return 0
    }
    if l == r {
        return heights[l]
    }
    minIdx := st.query(l, r)
    area1 := getMaxArea(heights, l, minIdx-1, st)
    area2 := getMaxArea(heights, minIdx+1, r, st)
    area3 := (r - l + 1) * heights[minIdx]

    maxArea := area1
    if area2 > maxArea {
        maxArea = area2
    }
    if area3 > maxArea {
        maxArea = area3
    }
    return maxArea
}

func largestRectangleArea(heights []int) int {
    n := len(heights)
    st := NewMinIdxSegtree(n, heights)
    return getMaxArea(heights, 0, n-1, st)
}
