           if node == nil { return nil }
           if oldToCopy[node] == nil {
               oldToCopy[node] = Node(0)
           }
           return oldToCopy[node]!
       }

       var cur = head
       while cur != nil {
           getNode(cur)!.val = cur!.val
           getNode(cur)!.next = getNode(cur!.next)
           getNode(cur)!.random = getNode(cur!.random)
           cur = cur!.next
       }

       return getNode(head)
   }
}
```

