		this.list.MoveToFront(node)
		node.Value = entry{key, value}
		return
	}

	if this.list.Len() == this.capacity {
		back := this.list.Back()
		this.list.Remove(back)
		delete(this.cache, back.Value.(entry).key)
	}

	node := this.list.PushFront(entry{key, value})
	this.cache[key] = node
