func kClosest(points [][]int, k int) [][]int {
    maxHeap := priorityqueue.NewWith(func(a, b interface{}) int {
        distA := a.([]int)[2]
        distB := b.([]int)[2]
        if distA > distB {
            return -1
        } else if distA < distB {
            return 1
        }
        return 0
    })

    for _, point := range points {
        x, y := point[0], point[1]
        dist := x*x + y*y
        maxHeap.Enqueue([]int{x, y, dist})
        if maxHeap.Size() > k {
            maxHeap.Dequeue()
        }
    }

    result := make([][]int, k)
    for i := k - 1; i >= 0; i-- {
        val, _ := maxHeap.Dequeue()
        point := val.([]int)
        result[i] = []int{point[0], point[1]}
    }

    return result
}
