                if (j > i && nums[j] == nums[j - 1]) {
                    continue
                }
                subset.add(nums[j])
                backtrack(j + 1, subset)
                subset.removeAt(subset.size - 1)
            }
        }

        backtrack(0, mutableListOf())
        return res
    }
