        }

        for c := 0; c < n; c++ {
            if col[c] || posDiag[r+c] || negDiag[r-c+n] {
                continue
            }

            col[c] = true
            posDiag[r+c] = true
            negDiag[r-c+n] = true
            board[r][c] = 'Q'

            backtrack(r + 1)

            col[c] = false
            posDiag[r+c] = false
            negDiag[r-c+n] = false
            board[r][c] = '.'
        }
    }

