            if (board[0][c] == 'O') {
                capture(0, c)
            }
            if (board[rows - 1][c] == 'O') {
                capture(rows - 1, c)
            }
        }

        for (r in 0 until rows) {
            for (c in 0 until cols) {
                if (board[r][c] == 'O') {
                    board[r][c] = 'X'
                } else if (board[r][c] == 'T') {
