            let item = minHeap.removeMin()
            let w1 = item.weight
            let n1 = item.node

            if visit.contains(n1) {
                continue
            }
            visit.insert(n1)
            t = w1

            if let neighbors = edges[n1] {
                for (n2, w2) in neighbors {
                    if !visit.contains(n2) {
                        minHeap.insert(Item(weight: w1 + w2, node: n2))
                    }
                }
            }
        }
        return visit.count == n ? t : -1
    }
