    func swimInWater(_ grid: [[Int]]) -> Int {
        let n = grid.count
        var visit = Array(repeating: Array(repeating: false, count: n), count: n)
        var minH = grid[0][0], maxH = grid[0][0]

        for row in 0..<n {
            for col in 0..<n {
                maxH = max(maxH, grid[row][col])
                minH = min(minH, grid[row][col])
            }
        }

        func dfs(_ node: (Int, Int), _ t: Int) -> Bool {
            let (r, c) = node
            if r < 0 || c < 0 || r >= n || c >= n || visit[r][c] || grid[r][c] > t {
                return false
            }
            if r == n - 1 && c == n - 1 {
                return true
            }
            visit[r][c] = true
            return dfs((r + 1, c), t) ||
                   dfs((r - 1, c), t) ||
                   dfs((r, c + 1), t) ||
                   dfs((r, c - 1), t)
        }

        var l = minH, r = maxH
        while l < r {
            let m = (l + r) >> 1
            if dfs((0, 0), m) {
                r = m
            } else {
                l = m + 1
            }
            for row in 0..<n {
                for col in 0..<n {
                    visit[row][col] = false
                }
            }
        }

        return r
    }
}
