                int count = entry.getValue();
                dp[i + 1].put(total + nums[i],
                          dp[i + 1].getOrDefault(total + nums[i], 0) + count);
                dp[i + 1].put(total - nums[i],
                          dp[i + 1].getOrDefault(total - nums[i], 0) + count);
