                for (dr, dc) in directions {
                    let nr = r + dr, nc = c + dc
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                        matrix[nr][nc] < matrix[r][c]) {
                        indegree[r][c] += 1
                    }
                }
            }
        }

        var q = Deque<(Int, Int)>()
        for r in 0..<rows {
            for c in 0..<cols {
                if indegree[r][c] == 0 {
                    q.append((r, c))
                }
            }
