        var LIS = 0
        while !q.isEmpty {
            for _ in 0..<q.count {
                let (r, c) = q.popFirst()!
                for (dr, dc) in directions {
                    let nr = r + dr, nc = c + dc
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                        matrix[nr][nc] > matrix[r][c]) {
                        indegree[nr][nc] -= 1
                        if indegree[nr][nc] == 0 {
                            q.append((nr, nc))
                        }
                    }
                }
            }
            LIS += 1
        }
