class Solution {
    func numDistinct(_ s: String, _ t: String) -> Int {
        let m = s.count, n = t.count
        var dp = [Int](repeating: 0, count: n + 1)
        dp[n] = 1
        let sArr = Array(s)
        let tArr = Array(t)

        for i in stride(from: m - 1, through: 0, by: -1) {
            var prev = 1
            for j in stride(from: n - 1, through: 0, by: -1) {
                let base = dp[j]
                var res = base
                if sArr[i] == tArr[j] {
                    if base > Int.max - prev {
                        res = 0
                    } else {
                        res += prev
                    }
                }
                prev = dp[j]
                dp[j] = res
            }
        }

        return dp[0]
    }
}
