                let coins = nums[i - 1] * nums[i] * nums[i + 1] +
                            dfs(Array(nums[..<i]) + Array(nums[(i + 1)...]))
                maxCoins = max(maxCoins, coins)
            }
            return maxCoins
        }

        return dfs(nums)
    }
}
```

