func mul(s string, d byte, zero int) string {
    i, carry := len(s)-1, 0
    d = d - '0'
    cur := make([]byte, 0)

    for i >= 0 || carry > 0 {
        var n int
        if i >= 0 {
            n = int(s[i] - '0')
        }
        prod := n*int(d) + carry
        cur = append(cur, byte(prod%10+'0'))
        carry = prod / 10
        i--
    }

    for i := 0; i < len(cur)/2; i++ {
        cur[i], cur[len(cur)-1-i] = cur[len(cur)-1-i], cur[i]
    }

    result := string(cur)
    for i := 0; i < zero; i++ {
        result += "0"
    }
    return result
}

func add(num1 string, num2 string) string {
    i, j, carry := len(num1)-1, len(num2)-1, 0
    res := make([]byte, 0)

    for i >= 0 || j >= 0 || carry > 0 {
        var n1, n2 int
        if i >= 0 {
            n1 = int(num1[i] - '0')
        }
        if j >= 0 {
            n2 = int(num2[j] - '0')
        }
        total := n1 + n2 + carry
        res = append(res, byte(total%10+'0'))
        carry = total / 10
        i--
        j--
    }

    for i := 0; i < len(res)/2; i++ {
        res[i], res[len(res)-1-i] = res[len(res)-1-i], res[i]
    }

    return string(res)
}
