            let n1 = i >= 0 ? Int(String(s1[i]))! : 0
            let n2 = j >= 0 ? Int(String(s2[j]))! : 0
            let total = n1 + n2 + carry
            res.append(String(total % 10))
            carry = total / 10
            i -= 1
            j -= 1
        }

