	for i := len(heights) - 2; i >= 0; i-- {
		if heights[i] > heights[res[len(res)-1]] {
			res = append(res, i)
		}
	}
	for i, j := 0, len(res)-1; i < j; i, j = i+1, j-1 {
		res[i], res[j] = res[j], res[i]
	}
	return res
}

