type visit struct {
	time int
	user string
	site string
}

type pattern struct {
	site1 string
	site2 string
	site3 string
}

func mostVisitedPattern(username []string, timestamp []int, website []string) []string {
	arr := make([]visit, len(username))
	for i := range username {
		arr[i] = visit{timestamp[i], username[i], website[i]}
	}
	sort.Slice(arr, func(i, j int) bool {
		return arr[i].time < arr[j].time
	})

	mp := make(map[string][]string)
	for _, v := range arr {
		mp[v.user] = append(mp[v.user], v.site)
	}

	count := make(map[pattern]int)
	for user := range mp {
		patterns := make(map[pattern]bool)
		cur := mp[user]
		for i := 0; i < len(cur); i++ {
			for j := i + 1; j < len(cur); j++ {
				for k := j + 1; k < len(cur); k++ {
					patterns[pattern{cur[i], cur[j], cur[k]}] = true
				}
			}
		}
		for p := range patterns {
			count[p]++
		}
	}

	maxCount := 0
	res := pattern{}
	for p := range count {
		if count[p] > maxCount || (count[p] == maxCount && comparePattern(p, res) < 0) {
			maxCount = count[p]
			res = p
		}
	}

	return []string{res.site1, res.site2, res.site3}
}

func comparePattern(p1, p2 pattern) int {
	if p1.site1 != p2.site1 {
		if p1.site1 < p2.site1 {
			return -1
		}
		return 1
	}
	if p1.site2 != p2.site2 {
		if p1.site2 < p2.site2 {
			return -1
		}
		return 1
	}
	if p1.site3 < p2.site3 {
		return -1
	}
	if p1.site3 > p2.site3 {
		return 1
	}
	return 0
}

