        for (int i = 0; i < Math.Min(word.Length, prefixLen); i++) {
            if (!node.Children.ContainsKey(word[i])) {
                return i;
            }
            node = node.Children[word[i]];
        }
        return Math.Min(word.Length, prefixLen);
