            if (right <= left + 1) {
                if (right == left + 1 && nums[right] < nums[left])
                    [nums[left], nums[right]] = [nums[right], nums[left]];
                return;
            }

            const j = partition(left, right);
            quickSort(left, j - 1);
            quickSort(j + 1, right);
        }

        quickSort(0, nums.length - 1);
        return nums;
