public class Solution {
    public int[] SortArray(int[] nums) {
        List<int> negatives = new List<int>();
        List<int> positives = new List<int>();

        foreach (int num in nums) {
            if (num < 0) negatives.Add(-num);
            else positives.Add(num);
        }

        if (negatives.Count > 0) {
            RadixSort(negatives);
            negatives.Reverse();
            for (int i = 0; i < negatives.Count; i++) {
                negatives[i] = -negatives[i];
            }
        }

        if (positives.Count > 0) {
            RadixSort(positives);
        }

        List<int> result = new List<int>();
        result.AddRange(negatives);
        result.AddRange(positives);

        return result.ToArray();
    }

    private void RadixSort(List<int> arr) {
        int n = arr.Count;
        int maxElement = 0;
        foreach (int num in arr) {
            if (num > maxElement) maxElement = num;
        }

        int d = 1;
        while (maxElement / d > 0) {
            CountSort(arr, n, d);
            d *= 10;
        }
    }

    private void CountSort(List<int> arr, int n, int d) {
        int[] count = new int[10];
        for (int i = 0; i < n; i++) {
            int digit = (arr[i] / d) % 10;
            count[digit]++;
        }

        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        int[] res = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int digit = (arr[i] / d) % 10;
            res[--count[digit]] = arr[i];
        }

        for (int i = 0; i < n; i++) {
            arr[i] = res[i];
        }
    }
}
