                for (let i = gap; i < n; i++) {
                    let key = nums[i];
                    let j = i - gap;
                    while (j >= 0 && nums[j] > key) {
                        nums[j + gap] = nums[j];
                        j -= gap;
                    }
                    nums[j + gap] = key;
                }
                gap = Math.floor(gap / 2);
            }
        };

        shellSort();
        return nums;
    }
}
```

```csharp
public class Solution {
    public int[] SortArray(int[] nums) {
        int n = nums.Length;
        if (n == 1) return nums;

        ShellSort(nums, n);
        return nums;
    }

    private void ShellSort(int[] nums, int n) {
        int gap = n / 2;
        while (gap >= 1) {
            for (int i = gap; i < n; i++) {
                int tmp = nums[i];
                int j = i - gap;
                while (j >= 0 && nums[j] > tmp) {
                    nums[j + gap] = nums[j];
                    j -= gap;
                }
                nums[j + gap] = tmp;
            }
            gap /= 2;
        }
    }
}
