                return [node, node.next];
            }
            const [newHead, nextNode] = reverseList(node.next, n - 1);
            node.next.next = node;
            node.next = nextNode;
            return [newHead, nextNode];
        };

        if (left === 1) {
            return reverseList(head, right)[0];
        }
        head.next = this.reverseBetween(head.next, left - 1, right - 1);
        return head;
    }
}
