public class Solution {
    public int rob(TreeNode root) {
        if (root == null) {
            return 0;
        }

        int res = root.val;
        if (root.left != null) {
            res += rob(root.left.left) + rob(root.left.right);
        }
        if (root.right != null) {
            res += rob(root.right.left) + rob(root.right.right);
