        int n = tasks.size();
        for (int i = 0; i < n; ++i) {
            tasks[i].push_back(i);
        }
        sort(tasks.begin(), tasks.end());

        vector<int> res;
        priority_queue<array<int, 2>, vector<array<int, 2>>, greater<>> minHeap;

        int i = 0;
        long long time = tasks[0][0];
