    wordBreak(s, wordDict) {
        const trie = new Trie();
        for (const word of wordDict) {
            trie.addWord(word);
        }

        const res = [];
        const backtrack = (index, path) => {
            if (index === s.length) {
                res.push(path.join(' '));
                return;
            }

            let node = trie.root;
            let word = '';
            for (let i = index; i < s.length; i++) {
                const char = s[i];
                if (!node.children.has(char)) {
                    break;
