func (t *Trie) addWord(word string) {
	curr := t.root
	for _, c := range word {
		if _, exists := curr.children[c]; !exists {
			curr.children[c] = newTrieNode()
		}
		curr = curr.children[c]
	}
	curr.isWord = true
