        }

        string[] sortedWords = (string[])words.Clone();
        Array.Sort(sortedWords, (w1, w2) => {
            for (int i = 0; i < Math.Min(w1.Length, w2.Length); i++) {
                if (w1[i] != w2[i]) {
                    return orderIndex[w1[i] - 'a'] - orderIndex[w2[i] - 'a'];
