            var res = new List<string>();
            for (int i = 0; i < 4; i++) {
                int digit = lockStr[i] - '0';
                string up = lockStr.Substring(0, i) + ((digit + 1) % 10) + lockStr.Substring(i + 1);
                string down = lockStr.Substring(0, i) + ((digit + 9) % 10) + lockStr.Substring(i + 1);
                res.Add(up);
                res.Add(down);
