		uf.par[x] = uf.par[uf.par[x]]
		x = uf.par[x]
	}
	return x
}

func (uf *UnionFind) union(x1, x2 int) bool {
	p1, p2 := uf.find(x1), uf.find(x2)
	if p1 == p2 {
		return false
	}

	if uf.rank[p1] > uf.rank[p2] {
		uf.par[p2] = p1
		uf.rank[p1] += uf.rank[p2]
	} else {
		uf.par[p1] = p2
		uf.rank[p2] += uf.rank[p1]
	}

