```csharp
public class DSU {
    private int[] parent;
    private int[] size;

    public DSU(int n) {
        parent = new int[n + 1];
        size = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public int Find(int node) {
        if (parent[node] != node) {
            parent[node] = Find(parent[node]);
        }
        return parent[node];
    }

    public bool Union(int u, int v) {
        int pu = Find(u);
        int pv = Find(v);
        if (pu == pv) return false;
        if (size[pu] < size[pv]) {
            (pu, pv) = (pv, pu);
        }
        size[pu] += size[pv];
        parent[pv] = pu;
        return true;
    }
}

public class Solution {
    public int MinimumEffortPath(int[][] heights) {
        int rows = heights.Length;
        int cols = heights[0].Length;
        List<(int, int, int)> edges = new List<(int, int, int)>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int id = r * cols + c;
                if (r + 1 < rows) {
                    int downId = (r + 1) * cols + c;
                    int diff = Math.Abs(heights[r][c] - heights[r + 1][c]);
                    edges.Add((diff, id, downId));
                }
                if (c + 1 < cols) {
                    int rightId = r * cols + (c + 1);
                    int diff = Math.Abs(heights[r][c] - heights[r][c + 1]);
                    edges.Add((diff, id, rightId));
                }
            }
        }

        edges.Sort((a, b) => a.Item1.CompareTo(b.Item1));
        DSU dsu = new DSU(rows * cols);

        foreach (var (weight, u, v) in edges) {
            dsu.Union(u, v);
            if (dsu.Find(0) == dsu.Find(rows * cols - 1)) {
                return weight;
            }
        }

        return 0;
    }
}
