        List<int>[] adj = new List<int>[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new List<int>();
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (GCD(nums[i], nums[j]) > 1) {
                    adj[i].Add(j);
                    adj[j].Add(i);
                }
            }
        }

        void DFS(int node) {
            visited[node] = true;
            foreach (int neighbor in adj[node]) {
                if (!visited[neighbor]) {
                    DFS(neighbor);
                }
            }
        }

        DFS(0);
        foreach (bool v in visited) {
            if (!v) return false;
        }

        return true;
    }

    private int GCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
