public class Solution {
    public int NumSquares(int n) {
        Queue<int> q = new Queue<int>();
        HashSet<int> seen = new HashSet<int>();

        int res = 0;
        q.Enqueue(0);

        while (q.Count > 0) {
            res++;
            int size = q.Count;
            for (int i = 0; i < size; i++) {
                int cur = q.Dequeue();
                int s = 1;
                while (s * s + cur <= n) {
