            dp[c] = int.MaxValue;
        }
        dp[COLS - 1] = 0;

        for (int r = ROWS - 1; r >= 0; r--) {
            for (int c = COLS - 1; c >= 0; c--) {
                dp[c] = grid[r][c] + Math.Min(dp[c], dp[c + 1]);
            }
        }

        return dp[0];
    }
}
```

