            while (j < n - 1) {
                if (arr[j] === arr[j + 1]) break;

                let curSign = arr[j] > arr[j + 1] ? 1 : 0;
                if (sign === curSign) break;

                sign = curSign;
                j++;
            }

            res = Math.max(res, j - i + 1);
        }

        return res;
    }
}
