## 1. Brute Force (Memoization)

::tabs-start

```python
class Solution:
    def canReach(self, s: str, minJump: int, maxJump: int) -> bool:
        n = len(s)
        dp = [None] * n
        dp[n - 1] = True

        def dfs(i):
            if dp[i] is not None:
                return dp[i]

            dp[i] = False
            for j in range(i + minJump, min(n, i + maxJump + 1)):
                if s[j] == '0' and dfs(j):
                    dp[i] = True
                    break

            return dp[i]

        if s[-1] == '1':
            return False
        return dfs(0)
```

```java
public class Solution {
    private Boolean[] dp;
    private int n;

    public boolean canReach(String s, int minJump, int maxJump) {
        this.n = s.length();
        this.dp = new Boolean[n];
        dp[n - 1] = true;

        if (s.charAt(n - 1) == '1') {
            return false;
        }

        return dfs(0, s, minJump, maxJump);
    }

    private boolean dfs(int i, String s, int minJump, int maxJump) {
        if (dp[i] != null) {
            return dp[i];
        }

        dp[i] = false;
        for (int j = i + minJump; j <= Math.min(n - 1, i + maxJump); j++) {
            if (s.charAt(j) == '0' && dfs(j, s, minJump, maxJump)) {
                dp[i] = true;
                break;
            }
        }
        return dp[i];
    }
}
```

