    canReach(s, minJump, maxJump) {
        const n = s.length;
        const dp = new Array(n).fill(null);
        dp[n - 1] = true;

        const dfs = (i) => {
            if (dp[i] !== null) {
                return dp[i];
            }

            dp[i] = false;
            for (let j = i + minJump; j <= Math.min(n - 1, i + maxJump); j++) {
                if (s[j] === '0' && dfs(j)) {
                    dp[i] = true;
                    break;
                }
            }
            return dp[i];
        };

        if (s[n - 1] === '1') {
            return false;
        }
        return dfs(0);
    }
}
```

