public class Solution {
    public bool CanReach(string s, int minJump, int maxJump) {
        int n = s.Length;
        bool?[] dp = new bool?[n];
        dp[n - 1] = true;

        bool Dfs(int i) {
            if (dp[i].HasValue) {
                return dp[i].Value;
            }

            dp[i] = false;
            for (int j = i + minJump; j <= Math.Min(n - 1, i + maxJump); j++) {
                if (s[j] == '0' && Dfs(j)) {
                    dp[i] = true;
                    break;
                }
            }

            return dp[i].Value;
        }

        if (s[n - 1] == '1') {
            return false;
        }

        return Dfs(0);
    }
}
