        Queue<int> R = new Queue<int>();
        int n = senate.Length;

        for (int i = 0; i < n; i++) {
            if (senate[i] == 'R') {
                R.Enqueue(i);
            } else {
                D.Enqueue(i);
            }
        }

        while (D.Count > 0 && R.Count > 0) {
            int dTurn = D.Dequeue();
            int rTurn = R.Dequeue();

            if (rTurn < dTurn) {
                R.Enqueue(rTurn + n);
            } else {
                D.Enqueue(dTurn + n);
            }
        }

        return R.Count > 0 ? "Radiant" : "Dire";
    }
}
