```javascript
class Solution {
    /**
     * @param {number} left
     * @param {number} right
     * @return {number}
     */
    rangeBitwiseAnd(left, right) {
        let res = 0;
        for (let i = 0; i < 32; i++) {
            const bit = (left >> i) & 1;
            if (!bit) {
                continue;
            }
            const next = Math.pow(2, i + 1);
            const remain = left % next;
            const diff = next - remain;
            if (right - left < diff) {
                res |= 1 << i;
            }
        }
        return res;
    }
}
```

