```python
class FreqStack:

    def __init__(self):
        self.cnt = defaultdict(int)
        self.stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)
        self.cnt[val] += 1

    def pop(self) -> int:
        maxCnt = max(self.cnt.values())
        i = len(self.stack) - 1
        while self.cnt[self.stack[i]] != maxCnt:
            i -= 1
        self.cnt[self.stack[i]] -= 1
        return self.stack.pop(i)
```

```java
public class FreqStack {
    private Map<Integer, Integer> cnt;
    private List<Integer> stack;

    public FreqStack() {
        cnt = new HashMap<>();
        stack = new ArrayList<>();
    }

    public void push(int val) {
        stack.add(val);
        cnt.put(val, cnt.getOrDefault(val, 0) + 1);
    }

    public int pop() {
        int maxCnt = Collections.max(cnt.values());
        int i = stack.size() - 1;
        while (cnt.get(stack.get(i)) != maxCnt) {
            i--;
        }
        int val = stack.remove(i);
        cnt.put(val, cnt.get(val) - 1);
        return val;
    }
}
```

```cpp
class FreqStack {
private:
    unordered_map<int, int> cnt;
    vector<int> stack;

public:
    FreqStack() {}

    void push(int val) {
        stack.push_back(val);
        cnt[val]++;
    }

    int pop() {
        int maxCnt = 0;
        for (auto& [_, frequency] : cnt) {
            maxCnt = max(maxCnt, frequency);
        }
        int i = stack.size() - 1;
        while (cnt[stack[i]] != maxCnt) {
            i--;
        }
        int val = stack[i];
        stack.erase(stack.begin() + i);
        cnt[val]--;
        return val;
    }
};
```

```javascript
class FreqStack {
    constructor() {
        this.cnt = new Map();
        this.stack = [];
    }

    /**
     * @param {number} val
     * @return {void}
     */
    push(val) {
        this.stack.push(val);
        this.cnt.set(val, (this.cnt.get(val) || 0) + 1);
    }

    /**
     * @return {number}
     */
    pop() {
        const maxCnt = Math.max(...this.cnt.values());
        let i = this.stack.length - 1;
        while (this.cnt.get(this.stack[i]) !== maxCnt) {
            i--;
        }
        const val = this.stack.splice(i, 1)[0];
        this.cnt.set(val, this.cnt.get(val) - 1);
        return val;
    }
}
```

```csharp
public class FreqStack {
    private Dictionary<int, int> cnt;
    private List<int> stack;

    public FreqStack() {
        cnt = new Dictionary<int, int>();
        stack = new List<int>();
    }

    public void Push(int val) {
        stack.Add(val);
        if (!cnt.ContainsKey(val)) {
            cnt[val] = 0;
        }
        cnt[val]++;
    }

    public int Pop() {
        int maxCnt = 0;
        foreach (var kvp in cnt) {
            maxCnt = Math.Max(maxCnt, kvp.Value);
        }

        for (int i = stack.Count - 1; i >= 0; i--) {
            int val = stack[i];
            if (cnt[val] == maxCnt) {
                cnt[val]--;
                stack.RemoveAt(i);
                return val;
            }
        }

        return -1;
    }
}
