        cnt = new Dictionary<int, int>();
        heap = new PriorityQueue<Entry, Entry>();
        index = 0;
    }

    public void Push(int val) {
        if (!cnt.ContainsKey(val)) {
            cnt[val] = 0;
        }
        cnt[val]++;
        var entry = new Entry(cnt[val], index++, val);
        heap.Enqueue(entry, entry);
    }

    public int Pop() {
        var entry = heap.Dequeue();
        cnt[entry.Value]--;
        return entry.Value;
    }
