func maxSumDistinctTriplet(x []int, y []int) int {
	negInf := math.MinInt64
	best := []pair{
		{-1, negInf},
		{-1, negInf},
		{-1, negInf},
	}

	for i := range x {
		xi, yi := x[i], y[i]
