		}

		if !found {
			if yi > best[0].y {
				best = []pair{{xi, yi}, best[0], best[1]}
			} else if yi > best[1].y {
				best = []pair{best[0], {xi, yi}, best[1]}
			} else if yi > best[2].y {
				best[2] = pair{xi, yi}
			}
		}
	}

	if best[2].y > negInf {
		return best[0].y + best[1].y + best[2].y
	}
	return -1
}

