		i, j := 0, pos2-1
		for i < pos1 && j >= 0 {
			if int64(nums1[i])*int64(nums2[j]) > prod {
				i++
			} else {
				cnt += int64(pos1 - i)
				j--
			}
		}

		i, j = pos1, n2-1
		for i < n1 && j >= pos2 {
			if int64(nums1[i])*int64(nums2[j]) > prod {
				j--
			} else {
				cnt += int64(j - pos2 + 1)
				i++
			}
		}

		i, j = 0, pos2
		for i < pos1 && j < n2 {
			if int64(nums1[i])*int64(nums2[j]) > prod {
				j++
			} else {
				cnt += int64(n2 - j)
				i++
			}
		}

		i, j = pos1, 0
		for i < n1 && j < pos2 {
			if int64(nums1[i])*int64(nums2[j]) > prod {
				i++
			} else {
				cnt += int64(n1 - i)
				j++
			}
		}

		return cnt
	}

	left, right := int64(-1e10), int64(1e10)
	for left <= right {
		mid := (left + right) / 2
		if count(mid) < k {
			left = mid + 1
		} else {
			right = mid - 1
		}
	}

	return left
}

