        bool[][] visit = new bool[ROWS][];
        for (int i = 0; i < ROWS; i++) visit[i] = new bool[COLS];
        int[][] direct = new int[][] {
            new int[] { 0, 1 }, new int[] { 0, -1 },
            new int[] { 1, 0 }, new int[] { -1, 0 }
        };

        int Dfs(int r, int c) {
            if (r < 0 || c < 0 || r == ROWS || c == COLS || grid[r][c] == 0 || visit[r][c])
                return 0;

            visit[r][c] = true;
            int res = 1;
            foreach (var d in direct) {
                res += Dfs(r + d[0], c + d[1]);
            }
            return res;
