                    (r === 0 || r === ROWS - 1 || c === 0 || c === COLS - 1)
                ) {
                    q.push([r, c]);
                    visit[r][c] = true;
                }
            }
        }

        while (!q.isEmpty()) {
            let [r, c] = q.pop();
            borderLand++;
            for (let d = 0; d < 4; d++) {
                let nr = r + direct[d],
                    nc = c + direct[d + 1];
                if (
                    nr >= 0 &&
                    nc >= 0 &&
                    nr < ROWS &&
                    nc < COLS &&
                    grid[nr][nc] === 1 &&
                    !visit[nr][nc]
                ) {
                    q.push([nr, nc]);
                    visit[nr][nc] = true;
