func numEnclaves(grid [][]int) int {
	ROWS, COLS := len(grid), len(grid[0])
	direct := [][]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}
	visit := make(map[[2]int]bool)

	var dfs func(r, c int) int
	dfs = func(r, c int) int {
		if r < 0 || c < 0 || r == ROWS || c == COLS || grid[r][c] == 0 {
			return 0
		}

		key := [2]int{r, c}
		if visit[key] {
			return 0
		}

		visit[key] = true
		res := 1

		for _, dir := range direct {
			dr, dc := dir[0], dir[1]
			res += dfs(r+dr, c+dc)
		}

		return res
	}

	land, borderLand := 0, 0

	for r := 0; r < ROWS; r++ {
		for c := 0; c < COLS; c++ {
			land += grid[r][c]

			key := [2]int{r, c}
			if grid[r][c] == 1 && !visit[key] && (c == 0 || c == COLS-1 || r == 0 || r == ROWS-1) {
				borderLand += dfs(r, c)
			}
		}
	}

	return land - borderLand
}

