            int j = i + 1;
            while (j < n && chars[i] == chars[j]) {
                j++;
            }

            if (j - i > 1) {
                s += (j - i).ToString();
            }
            i = j;
        }

        for (i = 0; i < s.Length; i++) {
            chars[i] = s[i];
        }
        return s.Length;
    }
}
