func (this *Solution) PickIndex() int {
	target := float64(this.prefix[len(this.prefix)-1]) * rand.Float64()
	l, r := 1, len(this.prefix)
	for l < r {
		mid := (l + r) >> 1
		if float64(this.prefix[mid]) <= target {
			l = mid + 1
		} else {
			r = mid
		}
	}
	return l - 1
}

