        foreach (var f in firstList) {
            if (!mp.ContainsKey(f[0])) mp[f[0]] = 0;
            mp[f[0]] += 1;
            if (!mp.ContainsKey(f[1] + 1)) mp[f[1] + 1] = 0;
            mp[f[1] + 1] -= 1;
        }
        foreach (var s in secondList) {
            if (!mp.ContainsKey(s[0])) mp[s[0]] = 0;
            mp[s[0]] += 1;
            if (!mp.ContainsKey(s[1] + 1)) mp[s[1] + 1] = 0;
            mp[s[1] + 1] -= 1;
