        int iPtr = 0, jPtr = 0;
        while (iPtr < n && jPtr < m) {
            jPtr = store[jPtr, s[iPtr] - 'a'] + 1;
            if (jPtr > m) return false;
            iPtr++;
        }

        return iPtr == n;
