        while (l < r) {
            int mid = l + (r - l) / 2;
            long coins = (long) mid * (mid + 1) / 2;
            if (coins <= n) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }

        return l - 1;
    }
}
