## 1. Sorting

::tabs-start

```python
class Solution:
    def maximumOddBinaryNumber(self, s: str) -> str:
        s = sorted(s)
        s.reverse()
        i = len(s) - 1
        while i >= 0 and s[i] == "0":
            i -= 1

        s[i], s[len(s) - 1] = s[len(s) - 1], s[i]
        return ''.join(s)
```

```java
public class Solution {
    public String maximumOddBinaryNumber(String s) {
        char[] arr = s.toCharArray();
        Arrays.sort(arr);
        reverse(arr);

        int n = arr.length;
        int i = n - 1;

        while (i >= 0 && arr[i] == '0') {
            i--;
        }

        char temp = arr[i];
        arr[i] = arr[n - 1];
        arr[n - 1] = temp;

        return new String(arr);
    }

    private void reverse(char[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            char temp = arr[left];
            arr[left++] = arr[right];
            arr[right--] = temp;
        }
    }
}
```

```cpp
class Solution {
public:
    string maximumOddBinaryNumber(string s) {
        sort(s.begin(), s.end(), greater<char>());

        int n = s.size(), i = n - 1;
        while (i >= 0 && s[i] == '0') {
            i--;
        }

        swap(s[i], s[n - 1]);
        return s;
    }
};
```

```javascript
class Solution {
    /**
     * @param {string} s
     * @return {string}
     */
    maximumOddBinaryNumber(s) {
        let arr = s.split('');
        arr.sort().reverse();

        let i = arr.length - 1;
        while (i >= 0 && arr[i] === '0') {
            i--;
        }

        [arr[i], arr[arr.length - 1]] = [arr[arr.length - 1], arr[i]];
        return arr.join('');
    }
}
```

