            if ((i > 0 && nums[i] == nums[i - 1]) ||
                (i + 1 < n && nums[i] == nums[i + 1])) {
                continue;
            }
            res.add(nums[i]);
        }

        return res.stream().mapToInt(i -> i).toArray();
    }
}
