        TrieNode cur = root;
        int n = w.length();
        for (int i = 0; i < n; i++) {
            String key = "" + w.charAt(i) + w.charAt(n - 1 - i);
            cur.children.putIfAbsent(key, new TrieNode());
            cur = cur.children.get(key);
            cur.count++;
        }
