        int n = w.length();
        for (int i = 0; i < n; i++) {
            String key = "" + w.charAt(i) + w.charAt(n - 1 - i);
            if (!cur.children.containsKey(key)) return 0;
            cur = cur.children.get(key);
        }
        return cur.count;
    }
}

