```csharp
public class Solution {
    public int ShortestBridge(int[][] grid) {
        int N = grid.Length;
        int[][] directions = new int[][] {
            new int[] {0, 1}, new int[] {0, -1},
            new int[] {1, 0}, new int[] {-1, 0}
        };

        bool Invalid(int r, int c) {
            return r < 0 || c < 0 || r == N || c == N;
        }

        HashSet<(int, int)> visit = new HashSet<(int, int)>();

        void Dfs(int r, int c) {
            if (Invalid(r, c) || grid[r][c] == 0 || visit.Contains((r, c)))
                return;
            visit.Add((r, c));
            foreach (var d in directions) {
                Dfs(r + d[0], c + d[1]);
            }
        }

        int Bfs() {
            int res = 0;
            Queue<(int, int)> q = new Queue<(int, int)>(visit);

            while (q.Count > 0) {
                int size = q.Count;
                for (int i = 0; i < size; i++) {
                    var (r, c) = q.Dequeue();
                    foreach (var d in directions) {
                        int curR = r + d[0], curC = c + d[1];
                        if (Invalid(curR, curC) || visit.Contains((curR, curC)))
                            continue;
                        if (grid[curR][curC] == 1)
                            return res;
                        q.Enqueue((curR, curC));
                        visit.Add((curR, curC));
                    }
                }
                res++;
            }
            return -1;
        }

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] == 1) {
                    Dfs(r, c);
                    return Bfs();
                }
            }
        }

        return -1;
    }
}
