public class Solution {
    public int ShortestBridge(int[][] grid) {
        int N = grid.Length;
        int[][] direct = new int[][] {
            new int[] {0, 1}, new int[] {0, -1}, new int[] {1, 0}, new int[] {-1, 0}
        };

        Queue<(int, int)> q = new Queue<(int, int)>();

        void Dfs(int r, int c) {
            if (r >= 0 && r < N && c >= 0 && c < N && grid[r][c] == 1) {
                grid[r][c] = 2;
                q.Enqueue((r, c));
                foreach (var d in direct) {
                    Dfs(r + d[0], c + d[1]);
                }
            }
        }

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] == 1) {
                    Dfs(r, c);
                    break;
                }
            }
            if (q.Count > 0) break;
        }

        int res = 0;
        while (q.Count > 0) {
            int size = q.Count;
            for (int i = 0; i < size; i++) {
                var (r, c) = q.Dequeue();
                foreach (var d in direct) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
                        if (grid[nr][nc] == 1) {
                            return res;
                        }
                        if (grid[nr][nc] == 0) {
                            grid[nr][nc] = 2;
                            q.Enqueue((nr, nc));
                        }
                    }
                }
            }
            res++;
        }
        return -1;
    }
}
