        if (i == n) {
            return 0;
        }

        int res = Integer.MAX_VALUE;
        for (int c = 0; c < 3; c++) {
            if (c == prevColor) {
                continue;
            }
            res = Math.min(res, costs[i][c] + dfs(i + 1, c));
