            if ((num & 1) == 1) {
                odd.add(num);
            } else {
                even.add(num);
            }
        }

        int idx = 0;
        for (int e : even) {
            nums[idx++] = e;
        }
        for (int o : odd) {
            nums[idx++] = o;
        }

        return nums;
    }
}
