            if (!count.ContainsKey(fruits[r])) {
                count[fruits[r]] = 0;
            }
            count[fruits[r]]++;

            if (count.Count > 2) {
                count[fruits[l]]--;
                if (count[fruits[l]] == 0) {
                    count.Remove(fruits[l]);
                }
                l++;
            }
        }

        return fruits.Length - l;
    }
}
