            for (int i = 0; i < size; i++) {
                var node = q.Dequeue();
                int idx = (res.Count % 2 == 1) ? size - i - 1 : i;
                level[idx] = node.val;
                if (node.left != null) q.Enqueue(node.left);
                if (node.right != null) q.Enqueue(node.right);
            }
            res.Add(level);
        }

        return res;
    }
}

