        memo = new int[triangle.Count][];
        for (int r = 0; r < triangle.Count; r++) {
            memo[r] = new int[triangle[r].Count];
            for (int c = 0; c < triangle[r].Count; c++) {
                memo[r][c] = INF;
            }
