class Solution {
    /**
     * @param {number[]} nums1
     * @param {number[]} nums2
     * @return {number[][]}
     */
    findDifference(nums1, nums2) {
        nums1.sort((a, b) => a - b);
        nums2.sort((a, b) => a - b);

        const helper = (A, B) => {
            const res = [];
            let j = 0;
            let prev = -Infinity;

            for (const num of A) {
                if (num === prev) continue;
                while (j < B.length && B[j] < num) j++;
                if (j === B.length || B[j] !== num) res.push(num);
                prev = num;
            }

            return res;
        };

        return [helper(nums1, nums2), helper(nums2, nums1)];
    }
}
