class Solution {
    /**
     * @param {number[]} nums
     * @return {number}
     */
    minOperations(nums) {
        const dfs = (cur) => {
            if (cur < 0) {
                return Infinity;
            }
            if (cur === 0) {
                return 0;
            }

            const ops = Math.min(dfs(cur - 2), dfs(cur - 3));
            return isFinite(ops) ? 1 + ops : ops;
        };

        const count = new Map();
        for (const num of nums) {
            count.set(num, (count.get(num) || 0) + 1);
        }

        let res = 0;
        for (const cnt of count.values()) {
            const op = dfs(cnt);
            if (op === Infinity) {
                return -1;
            }
            res += op;
        }

        return res;
    }
}
