private:
    bool isValid(string s, int size, int k) {
        int n = s.length();
        unordered_map<char, int> counter;

        for (int i = 0; i < size; i++) {
            char c = s[i];
            counter[c]++;
        }

        if (counter.size() <= k) {
            return true;
        }

        for (int i = size; i < n; i++) {
            char c1 = s[i];
            counter[c1]++;
            char c2 = s[i - size];
            counter[c2]--;
            if (counter[c2] == 0) {
                counter.erase(c2);
            }
            if (counter.size() <= k) {
                return true;
            }
        }

        return false;
    }
};
