    /**
     * @param {number[]} arr
     * @param {number} fromIndex
     * @param {number} toIndex
     * @param {number} target
     * @return {number}
     */
    binarySearch(arr, fromIndex, toIndex, target) {
        let left = fromIndex, right = toIndex - 1;
        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            if (arr[mid] === target) {
                return mid;
            } else if (arr[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -(left + 1);
    }
}
```

