                curr = 0;
                previousOperator = c;
            }

            i[0]++;
        }

        int ans = 0;
        for (int num: stack) {
            ans += num;
        }

        return ans;
    }

    public int calculate(String s) {
        s += "@";
        int[] i = new int[1];
        return solve(s, i);
    }
