        for (int num : nums) {
            q.push(num);
        }
    }

    int showFirstUnique() {
        queue<int> temp = q;
        while (!temp.empty()) {
            int num = temp.front();
            temp.pop();

            int count = 0;
            queue<int> countTemp = q;
            while (!countTemp.empty()) {
                if (countTemp.front() == num) count++;
                countTemp.pop();
            }

            if (count == 1) {
                return num;
            }
        }
        return -1;
    }

    void add(int value) {
        q.push(value);
    }
