            this->add(num);
        }
    }

    int showFirstUnique() {
        while (!q.empty() && !isUnique[q.front()]) {
            q.pop();
        }

        if (!q.empty()) {
            return q.front();
        }

        return -1;
    }

    void add(int value) {
        if (isUnique.find(value) == isUnique.end()) {
            isUnique[value] = true;
            q.push(value);
        } else {
            isUnique[value] = false;
        }
    }
};
