## 1. Monotonic Stack

::tabs-start

```python
class Solution:
    def verifyPreorder(self, preorder: List[int]) -> bool:
        min_limit = float('-inf')
        stack = []

        for num in preorder:
            while stack and stack[-1] < num:
                min_limit = stack.pop()

            if num <= min_limit:
                return False

            stack.append(num)

        return True
```

```java
class Solution {
    public boolean verifyPreorder(int[] preorder) {
        int minLimit = Integer.MIN_VALUE;
        Stack<Integer> stack = new Stack<>();

        for (int num: preorder) {
            while (!stack.isEmpty() && stack.peek() < num) {
                minLimit = stack.pop();
            }

            if (num <= minLimit) {
                return false;
            }

            stack.push(num);
        }

        return true;
    }
}
```

