                                next_row = curr[0] + dir[0]
                                next_col = curr[1] + dir[1]

                                # For each cell with the value equal to empty land value
                                # add distance and decrement the cell value by 1.
                                if (0 <= next_row < rows and
                                    0 <= next_col < cols and
